WITH x10 AS (SELECT SUM(x7.v34970 + x7.v34970) AS x12, x7.v34970 AS x13 FROM x14 AS x20, x15 AS x21 WHERE x7.v34970 = x7.v34971 GROUP BY x7.v34971) SELECT x7.v34970, x7.v34970, ANY_VALUE(x7.v34970) + x7.v34970 AS x4, x7.v34970 FROM v34969 AS x7 WHERE NOW() BETWEEN CURRENT_DATE - INTERVAL '1' DAY AND CURRENT_DATE